import { useState, useEffect, useRef } from 'react';
import { useNavigate, useParams, Routes, Route } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../components/Toast';
import ConfirmDialog from '../components/ConfirmDialog';
import Spinner from '../components/Spinner';
import {
  getAlbumsByUser, createAlbum, deleteAlbum,
  getPhotosByAlbum, createPhoto, updatePhoto, deletePhoto
} from '../services/api';
import '../styles/Albums.css';

function AlbumList() {
  const { user } = useAuth();
  const { userId } = useParams();
  const navigate = useNavigate();
  const toast = useToast();

  const [albums, setAlbums] = useState([]);
  const [covers, setCovers] = useState({}); // שמירת תמונות הכריכה של האלבומים
  const [loading, setLoading] = useState(true);
  const [searchId, setSearchId] = useState('');
  const [searchTitle, setSearchTitle] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [newAlbumTitle, setNewAlbumTitle] = useState('');
  const [confirmDelete, setConfirmDelete] = useState(null);

  useEffect(() => { fetchAlbums(); }, [userId]);

  const fetchAlbums = async () => {
    setLoading(true);
    try {
      const data = await getAlbumsByUser(userId);
      const fetchedAlbums = Array.isArray(data) ? data : (Array.isArray(data?.data) ? data.data : []);
      setAlbums(fetchedAlbums);

      // משיכה חכמה ובטוחה של התמונה הראשונה מכל אלבום עבור הכריכה
      fetchedAlbums.forEach(async (album) => {
        try {
          const res = await getPhotosByAlbum(album.id, 1, 1);
          const coverPhotos = Array.isArray(res) ? res : (Array.isArray(res?.data) ? res.data : []);
          if (coverPhotos.length > 0) {
            setCovers(prev => ({ ...prev, [album.id]: coverPhotos[0].url || coverPhotos[0].thumbnailUrl }));
          }
        } catch {}
      });

    } catch (err) {
      toast('Failed to load albums', 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleAdd = async () => {
    if (!newAlbumTitle.trim()) return;
    try {
      const added = await createAlbum({ userId: userId, title: newAlbumTitle.trim() });
      setAlbums((prev) => [...prev, added]);
      setNewAlbumTitle('');
      setIsAdding(false);
      toast('New destination added!');
    } catch (err) {
      toast('Failed to create album', 'error');
    }
  };

  const handleDelete = async (id) => {
    try {
      await deleteAlbum(id, userId);
      setAlbums((prev) => prev.filter((a) => a.id !== id));
      setConfirmDelete(null);
      toast('Album deleted');
    } catch (err) {
      toast('Failed to delete album', 'error');
    }
  };

  const filtered = albums.filter((a) => {
    if (searchId && !String(a.id).includes(searchId)) return false;
    if (searchTitle && !a.title.toLowerCase().includes(searchTitle.toLowerCase())) return false;
    return true;
  });

  return (
    <div className="albums-page">
      <div className="page-header">
        <button className="btn-home" onClick={() => navigate(`/users/${userId}`)}>🏠 Home</button>
        <h2>📷 My Travel Destinations</h2>
      </div>

      <div className="albums-toolbar">
        <input placeholder="Search ID" value={searchId} onChange={(e) => setSearchId(e.target.value)} />
        <input placeholder="Search destination" value={searchTitle} onChange={(e) => setSearchTitle(e.target.value)} />
      </div>

      {loading ? <Spinner text="Loading your albums..." /> : (
        <div className="albums-grid">
          <div className={`album-card add-card ${isAdding ? 'active' : ''}`} onClick={() => !isAdding && setIsAdding(true)}>
            {isAdding ? (
              <div className="album-add-inline" onClick={(e) => e.stopPropagation()}>
                <input 
                  value={newAlbumTitle} 
                  onChange={(e) => setNewAlbumTitle(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleAdd()}
                  placeholder="Destination Name" 
                  autoFocus 
                />
                <div className="add-actions-modern">
                  <button className="btn-primary" onClick={handleAdd}>Save</button>
                  <button className="btn-secondary" onClick={() => setIsAdding(false)}>Cancel</button>
                </div>
              </div>
            ) : (
              <div className="add-placeholder"><span>➕</span><p>New Destination</p></div>
            )}
          </div>

          {filtered.map((album) => (
            <div key={album.id} className="album-card" onClick={() => navigate(`/users/${userId}/albums/${album.id}/photos`)}>
              {/* הצגת תמונת הכריכה אם קיימת, אחרת הצגת המפה המעוצבת */}
              {covers[album.id] ? (
                <img className="album-cover-img" src={covers[album.id]} alt={album.title} />
              ) : (
                <div className="album-cover-placeholder">🗺️</div>
              )}
              <div className="album-info">
                <span className="album-id">#{String(album.id).substring(0,4)}</span>
                <span className="album-title">{album.title}</span>
              </div>
              <div className="album-footer">
                <button className="album-delete" onClick={(e) => { e.stopPropagation(); setConfirmDelete(album.id); }}>🗑️</button>
              </div>
            </div>
          ))}
        </div>
      )}

      {confirmDelete && (
        <ConfirmDialog
          message="Delete this destination and all its photos?"
          onConfirm={() => handleDelete(confirmDelete)}
          onCancel={() => setConfirmDelete(null)}
        />
      )}
    </div>
  );
}

function AlbumPhotos() {
  const { userId, albumId } = useParams();
  const navigate = useNavigate();
  const toast = useToast();
  const fileInputRef = useRef(null);

  const [photos, setPhotos] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(false);
  const [isAdding, setIsAdding] = useState(false);
  const [newPhotoTitle, setNewPhotoTitle] = useState('');
  const [newPhotoUrl, setNewPhotoUrl] = useState('');
  const [editPhotoId, setEditPhotoId] = useState(null);
  const [editPhotoTitle, setEditPhotoTitle] = useState('');
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [lightbox, setLightbox] = useState(null);

  const LIMIT = 6;

  useEffect(() => { loadPhotos(1, true); }, [albumId]);

  const loadPhotos = async (pageNum, reset = false) => {
    setLoading(true);
    try {
      const res = await getPhotosByAlbum(albumId, pageNum, LIMIT);
      const fetchedPhotos = Array.isArray(res) ? res : (Array.isArray(res?.data) ? res.data : []);
      setPhotos((prev) => reset ? fetchedPhotos : [...prev, ...fetchedPhotos]);
      setHasMore(fetchedPhotos.length === LIMIT);
      setPage(pageNum);
    } catch (err) {
      toast('Failed to load photos', 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleAddPhoto = async () => {
    // מאפשרים כותרת ריקה לחלוטין (אופציונלי)
    const finalTitle = newPhotoTitle.trim();
    const url = newPhotoUrl || `https://picsum.photos/seed/${Math.random()}/600/400`;
    try {
      const added = await createPhoto({ albumId: albumId, title: finalTitle, url, thumbnailUrl: url });
      setPhotos((prev) => [added, ...prev]);
      setNewPhotoTitle(''); setNewPhotoUrl(''); setIsAdding(false);
      toast('Photo added to gallery!');
    } catch (err) {
      toast('Failed to add photo', 'error');
    }
  };

  const handleEditSave = async (photo) => {
    try {
      const updated = await updatePhoto(photo.id, { ...photo, title: editPhotoTitle });
      setPhotos((prev) => prev.map((p) => (p.id === photo.id ? updated : p)));
      setEditPhotoId(null);
      toast('Caption updated');
    } catch (err) {
      toast('Update failed', 'error');
    }
  };

  const handleDeletePhoto = async (id) => {
    await deletePhoto(id);
    setPhotos((prev) => prev.filter((p) => p.id !== id));
    setConfirmDelete(null);
    toast('Photo removed', 'error');
  };

  // המרה קבועה ל-Base64 לשמירה יציבה במסד הנתונים
  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => { setNewPhotoUrl(reader.result); };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="photos-page">
      <div className="photos-header">
        <button className="btn-back" onClick={() => navigate(`/users/${userId}/albums`)}>← Back</button>
        <h2>Memories of Album #{String(albumId).substring(0,4)}</h2>
      </div>

      <div className="photos-grid">
        {/* טופס הוספה מודרני, מרווח ומעוצב */}
        <div className={`photo-card add-card-modern ${isAdding ? 'active' : ''}`} onClick={() => !isAdding && setIsAdding(true)}>
          {isAdding ? (
            <div className="photo-add-inline" onClick={(e) => e.stopPropagation()}>

              <div className="inline-field">
                <label>1. Select Image</label>
                <input type="file" ref={fileInputRef} hidden onChange={handleFileUpload} accept="image/*" />
                <button className="btn-upload-custom" onClick={() => fileInputRef.current.click()}>
                  {newPhotoUrl ? '🖼️ Image Selected (Change)' : '📁 Browse from computer'}
                </button>
              </div>

              <div className="inline-field">
                <label>2. Caption (Optional)</label>
                <input 
                  value={newPhotoTitle} 
                  onChange={(e) => setNewPhotoTitle(e.target.value)} 
                  placeholder="Leave empty or write a title..." 
                />
              </div>

              <div className="add-actions-modern">
                <button className="btn-primary" onClick={handleAddPhoto}>Add Memory</button>
                <button className="btn-secondary" onClick={() => { setIsAdding(false); setNewPhotoUrl(''); setNewPhotoTitle(''); }}>Cancel</button>
              </div>

            </div>
          ) : (
            <div className="add-placeholder"><span>📸</span><p>Add Memory</p></div>
          )}
        </div>

        {photos.map((photo) => (
          <div key={photo.id} className="photo-card">
            <div className="photo-img-frame">
              <img src={photo.thumbnailUrl} alt={photo.title || 'Travel memory'} onClick={() => setLightbox(photo)} />
            </div>

            {editPhotoId === photo.id ? (
              <div className="photo-edit">
                <input value={editPhotoTitle} onChange={(e) => setEditPhotoTitle(e.target.value)} autoFocus />
                <button onClick={() => handleEditSave(photo)}>💾</button>
                <button onClick={() => setEditPhotoId(null)}>✕</button>
              </div>
            ) : (
              // אם אין כותרת, לא נתפוס סתם מקום או שנציג רווח עדין
              photo.title ? <p className="photo-title">{photo.title}</p> : <div className="photo-spacer" />
            )}

            <div className="photo-actions">
              <button onClick={() => { setEditPhotoId(photo.id); setEditPhotoTitle(photo.title || ''); }}>✏️</button>
              <button onClick={() => setConfirmDelete(photo.id)}>🗑️</button>
            </div>
          </div>
        ))}
      </div>

      {hasMore && !loading && (
        <div className="load-more">
          <button className="btn-secondary" onClick={() => loadPhotos(page + 1)}>View More Memories</button>
        </div>
      )}

      {lightbox && (
        <div className="lightbox-overlay" onClick={() => setLightbox(null)}>
          <div className="lightbox-content" onClick={(e) => e.stopPropagation()}>
            <button className="lightbox-close" onClick={() => setLightbox(null)}>✕</button>
            <img src={lightbox.url} alt={lightbox.title || 'Memory'} />
            {lightbox.title && <p>{lightbox.title}</p>}
          </div>
        </div>
      )}

      {confirmDelete && (
        <ConfirmDialog
          message="Remove this memory forever?"
          onConfirm={() => handleDeletePhoto(confirmDelete)}
          onCancel={() => setConfirmDelete(null)}
        />
      )}
    </div>
  );
}

export default function Albums() {
  return (
    <Routes>
      <Route index element={<AlbumList />} />
      <Route path=":albumId/photos" element={<AlbumPhotos />} />
    </Routes>
  );
}
